#include "Renderer/MoresamplerProcess.h"
#include <QFileInfo>
#include <QTimer>
namespace myvocal { MoresamplerProcess::MoresamplerProcess(QObject*p):QObject(p){} void MoresamplerProcess::setExecutable(const QString&p){m_executable=p;} ResamplerResult MoresamplerProcess::render(const QString&in,const QString&out,int note,double velocity,double pitch,int timeoutMs){ResamplerResult r;r.outputPath=out;if(m_executable.isEmpty()){r.error=QStringLiteral("moresampler.exe path is not configured");return r;}if(!QFileInfo::exists(m_executable)){r.error=QStringLiteral("Resampler not found: ")+m_executable;return r;}m_process.start(m_executable,QStringList{in,out,QString::number(note),QString::number(velocity),QString::number(pitch,'f',4)});if(!m_process.waitForStarted(2000)){r.error=m_process.errorString();return r;}if(!m_process.waitForFinished(timeoutMs)){m_process.kill();m_process.waitForFinished(1000);r.error=QStringLiteral("Resampler timeout");return r;}r.exitCode=m_process.exitCode();r.success=(m_process.exitStatus()==QProcess::NormalExit&&r.exitCode==0&&QFileInfo::exists(out));if(!r.success){r.error=QString::fromLocal8Bit(m_process.readAllStandardError());if(r.error.isEmpty())r.error=QStringLiteral("Resampler failed with exit code %1").arg(r.exitCode);}return r;}void MoresamplerProcess::cancel(){if(m_process.state()!=QProcess::NotRunning)m_process.kill();} }
